Modify the app.js to make the port configurable via environment variables:

```javascript
const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// ... routes ...

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

