const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const app = express();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: process.env.CSP_ENABLED === 'true' ? undefined : false,
}));

app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  credentials: process.env.CORS_CREDENTIALS === 'true' || true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // default 15 minutes
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100, // default 100 requests per window
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ 
  limit: process.env.BODY_LIMIT_JSON || '10kb' 
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: process.env.BODY_LIMIT_URL_ENCODED || '10kb' 
}));

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: process.env.SERVICE_NAME || 'secure-node-app',
    environment: process.env.NODE_ENV || 'development'
  });
});

app.get('/users', (req, res) => {
  // In a real app, you would validate and sanitize inputs here
  // For demonstration, we're returning static data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Centralized error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PARTOSSIBLE_TYPES: [STRING]}`);
});

module.exports = app;

